import React, { useState } from "react";
import styled from "styled-components";

const PopupContainer = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50%;
  padding: 20px;
  background-color: white;
  border-radius: 8px;
  border: 2px solid rgb(121, 145, 168); 
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
`;

const Title = styled.h2`
  text-align: center;
  margin-bottom: 20px;
  position: relative;
  font-size: 30px;
  font-weight: bold
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background: none;
  border: none;
  font-size: 20px;
  color: #aaa;
  cursor: pointer;

  &:hover {
    color: #f00;
  }
`;

const InfoWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 15px;
`;

const InfoRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const InputField = styled.input`
  padding: 10px;
  margin: 5px 0;
  border: 1px solid #ccc;
  border-radius: 4px;
  width: 100%;
`;

const Label = styled.label`
  font-weight: bold;
  min-width: 120px;
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: space-between;
  margin-top: 20px;
`;

const Button = styled.button`
  padding: 10px 15px;
  background-color: #007bff; /* Blue color */
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:disabled {
    background-color: #ccc;
    cursor: not-allowed;
  }

  &:hover {
    background-color: #0056b3; /* Darker blue */
  }
`;

const UserInfoPopup = ({ openPopup, closePopup }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [userInfo, setUserInfo] = useState({
    email: "user@example.com",
    fullName: "Nguyen Van A",
    phone: "0123456789",
    address: "123 Main St, HCM City",
    birthDate: "1990-01-01",
    gender: "Nam",
    occupation: "Software Developer",
    workPlace: "ABC Corp"
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUserInfo((prevInfo) => ({
      ...prevInfo,
      [name]: value
    }));
  };

  return (
    openPopup && (
      <PopupContainer>
        <Title>Thông tin người dùng</Title>
        <CloseButton onClick={closePopup}>×</CloseButton>
        <InfoWrapper>
          {Object.entries(userInfo).map(([key, value]) => {
            let labelText;
            switch (key) {
              case "phone":
                labelText = "Số điện thoại";
                break;
              case "address":
                labelText = "Địa chỉ";
                break;
              case "gender":
                labelText = "Giới tính";
                break;
              case "fullName":
                labelText = "Họ và tên";
                break;
              case "workPlace":
                labelText = "Địa điểm làm việc";
                break;
              case "birthDate":
                labelText = "Ngày sinh";
                break;
              case "occupation":
                labelText = "Nghề nghiệp";
                break;
              case "email":
                labelText = "Email";
                break;
              default:
                labelText = key.charAt(0).toUpperCase() + key.slice(1);
            }

            return (
              <InfoRow key={key}>
                <Label>{labelText}</Label>
                {isEditing ? (
                  <InputField
                    type={key === "birthDate" ? "date" : "text"}
                    name={key}
                    value={value}
                    onChange={handleChange}
                  />
                ) : (
                  <span>{value}</span>
                )}
              </InfoRow>
            );
          })}
        </InfoWrapper>
        <ButtonWrapper>
          <Button
            onClick={() => setIsEditing(true)}
            disabled={isEditing} // Disable "Chỉnh sửa" when editing
          >
            Chỉnh sửa
          </Button>
          <Button
            onClick={() => setIsEditing(false)}
            disabled={!isEditing} // Disable "Xác nhận" when not editing
          >
            Xác nhận
          </Button>
        </ButtonWrapper>
      </PopupContainer>
    )
  );
};

export default UserInfoPopup;
